(45990, 'Job 19:2', 'Job', 19, 2, '”تۀ به تر کومې پورې ما له تکليف راکوې، او په خپلو خبرو به زما زړۀ غوڅوې؟', '”تۀ به تر کومې پورې ما له تکلیف راکوې، او په خپلو خبرو به زما زرۀ غوچوې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45991, 'Job 19:3', 'Job', 19, 3, 'تا لس ځلې زما بې‌عزتى کړې ده، تۀ چې ما له کوم تکليف راکوې په هغې تۀ شرمېږې نۀ څۀ؟', 'تا لس جلې زما بې‌عزتی کرې ده، تۀ چې ما له کوم تکلیف راکوې په هغې تۀ شرمېزې نۀ چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45992, 'Job 19:4', 'Job', 19, 4, 'او کۀ دا رښتيا هم وى چې ما غلطى کړې ده، نو ستا په کښې څۀ کار دے؟', 'او کۀ دا رشتیا هم وی چې ما غلطی کرې ده، نو ستا په کشې چۀ کار دے؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45993, 'Job 19:5', 'Job', 19, 5, 'تۀ په خپل نظر کښې زما نه لوئ يې، زما تکليف د ګناه د ثبوت دپاره استعمالوې.', 'تۀ په خپل نظر کشې زما نه لوی یې، زما تکلیف د ګناه د ثبوت دپاره استعمالوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45994, 'Job 19:6', 'Job', 19, 6, 'نو بيا پوهه شه چې خُدائ پاک زۀ په غلطه کړے يم، او زما نه ګېرچاپېره يې جال خور کړے دے.', 'نو بیا پوهه شه چې خدای پاک زۀ په غلطه کرے یم، او زما نه ګېرچاپېره یې جال خور کرے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45995, 'Job 19:7', 'Job', 19, 7, 'ګوره، زۀ د فرياد چغې هم وهم، خو څوک ما له جواب نۀ شى راکولے، زۀ په زوره زوره چغې وهم، خو اِنصاف نشته.', 'ګوره، زۀ د فریاد چغې هم وهم، خو چوک ما له جواب نۀ شی راکولے، زۀ په زوره زوره چغې وهم، خو انصاف نشته.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45996, 'Job 19:8', 'Job', 19, 8, 'خُدائ پاک زما لارې بندې کړې دى او زۀ خوځېدے نۀ شم، او هغۀ زما په لار کښې تيارې جوړې کړې دى.', 'خدای پاک زما لارې بندې کرې دی او زۀ خوجېدے نۀ شم، او هغۀ زما په لار کشې تیارې جورې کرې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45997, 'Job 19:9', 'Job', 19, 9, 'هغۀ زما نه عزت اخستے دے، او زما د سر نه يې تاج اخوا کړے دے.', 'هغۀ زما نه عزت اخستے دے، او زما د سر نه یې تاج اخوا کرے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45998, 'Job 19:10', 'Job', 19, 10, 'هغه د هر طرف نه ما راغورزوى او زۀ ختم يم، هغۀ د ونې په شان زما د اُميد جرړې راويستلې دى.', 'هغه د هر طرف نه ما راغورزوی او زۀ ختم یم، هغۀ د ونې په شان زما د امید جررې راویستلې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45999, 'Job 19:11', 'Job', 19, 11, 'هغه زما خِلاف سخت غصه شوے دے، او هغه مې خپل دشمن ګڼى.', 'هغه زما خلاف سخت غصه شوے دے، او هغه مې خپل دشمن ګنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(46000, 'Job 19:12', 'Job', 19, 12, 'د هغۀ فوجيان راغونډ شوى دى، هغوئ په ما باندې حملې دپاره لارې تيارې کړې دى. او زما د خېمې نه ګېرچاپېره يې خېمې لګولې دى.', 'د هغۀ فوجیان راغوند شوی دی، هغوی په ما باندې حملې دپاره لارې تیارې کرې دی. او زما د خېمې نه ګېرچاپېره یې خېمې لګولې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46001, 'Job 19:13', 'Job', 19, 13, 'زما خپلوان ما نه ځان لرې ساتى، او زما دوستان زما خلاف شوى دى.', 'زما خپلوان ما نه جان لرې ساتی، او زما دوستان زما خلاف شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46002, 'Job 19:14', 'Job', 19, 14, 'زما خپلوانو او زما نزدې دوستانو زۀ پرېښے او هېر کړے يم،', 'زما خپلوانو او زما نزدې دوستانو زۀ پرېشے او هېر کرے یم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46003, 'Job 19:15', 'Job', 19, 15, 'زما په کور کښې مېلمنو زۀ هېر کړے يم، زما وينځې ما پردے سړے ګڼى، زۀ د هغوئ په نظر کښې يو مسافر يم.', 'زما په کور کشې مېلمنو زۀ هېر کرے یم، زما وینجې ما پردے سرے ګنی، زۀ د هغوی په نظر کشې یو مسافر یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46004, 'Job 19:16', 'Job', 19, 16, 'زۀ چې خپل نوکر راوغواړم نو هغه ما له نۀ راځى، زۀ هغۀ ته سوال زارى کوم.', 'زۀ چې خپل نوکر راوغوارم نو هغه ما له نۀ راجی، زۀ هغۀ ته سوال زاری کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46005, 'Job 19:17', 'Job', 19, 17, 'زما د خولې بوئ هم زما په ښځه باندې بد لګى، زما خپل خاندان زما نه نفرت کوى.', 'زما د خولې بوی هم زما په شجه باندې بد لګی، زما خپل خاندان زما نه نفرت کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46006, 'Job 19:18', 'Job', 19, 18, 'واړۀ ماشومان هم ما ته سپک ګورى، کله چې زۀ هغوئ سره خبرې کول غواړم نو هغوئ ما ته شا کړى.', 'وارۀ ماشومان هم ما ته سپک ګوری، کله چې زۀ هغوی سره خبرې کول غوارم نو هغوی ما ته شا کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46007, 'Job 19:19', 'Job', 19, 19, 'زما نزدې ملګرى زما نه نفرت کوى، او چې د چا سره ما مينه کوله نو هغوئ زما نه مخ اړولے دے.', 'زما نزدې ملګری زما نه نفرت کوی، او چې د چا سره ما مینه کوله نو هغوی زما نه مخ ارولے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46008, 'Job 19:20', 'Job', 19, 20, 'په ما کښې صرف هډوکى او څرمن پاتې دى او ډېر په مشکله د مرګ نه تښتېدلے يم.', 'په ما کشې صرف هدوکی او چرمن پاتې دی او دېر په مشکله د مرګ نه تشتېدلے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46009, 'Job 19:21', 'Job', 19, 21, 'اے زما دوستانو، په ما باندې رحم وکړئ، په ما باندې رحم وکړئ، ځکه چې د خُدائ پاک ګزار زۀ وهلے يم.', 'اے زما دوستانو، په ما باندې رحم وکری، په ما باندې رحم وکری، جکه چې د خدای پاک ګزار زۀ وهلے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(46010, 'Job 19:22', 'Job', 19, 22, 'تاسو د خُدائ پاک په شان ولې ما پسې يئ، تاسو زۀ ښۀ نۀ يم کړولے څۀ؟', 'تاسو د خدای پاک په شان ولې ما پسې یی، تاسو زۀ شۀ نۀ یم کرولے چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46011, 'Job 19:23', 'Job', 19, 23, 'کاش چې زما خبرې ليکلے شوے وے، کاش چې زما خبرې په يو کِتاب کښې بيان شوے وے.', 'کاش چې زما خبرې لیکلے شوے وے، کاش چې زما خبرې په یو کتاب کشې بیان شوے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46012, 'Job 19:24', 'Job', 19, 24, 'کاش چې د اوسپنې او د پيتلو د قلم سره دا خبرې په يو ګټ باندې د تل دپاره نقش شوے وے.', 'کاش چې د اوسپنې او د پیتلو د قلم سره دا خبرې په یو ګت باندې د تل دپاره نقش شوے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46013, 'Job 19:25', 'Job', 19, 25, 'زما يقين دے چې زما خلاصونکے ژوندے دے، او چې په آخر کښې به هغه د زمکې دپاسه ودريږى،', 'زما یقین دے چې زما خلاصونکے ژوندے دے، او چې په اخر کشې به هغه د زمکې دپاسه ودریزی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(46014, 'Job 19:26', 'Job', 19, 26, 'او چې کله زما څرمن بلکل ختمه شى، نو بيا به زۀ په خپلو سترګو خُدائ پاک ووينم،', 'او چې کله زما چرمن بلکل ختمه شی، نو بیا به زۀ په خپلو سترګو خدای پاک ووینم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(46015, 'Job 19:27', 'Job', 19, 27, 'زۀ به هغه په خپله وګورم، او زۀ به هغه په خپلو سترګو ووينم. ما سره صرف هم دغه فکر دے.', 'زۀ به هغه په خپله وګورم، او زۀ به هغه په خپلو سترګو ووینم. ما سره صرف هم دغه فکر دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_19_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
